/* Source-backed transportation education. Company policies require confirmation. */
(function(root){
 const sources={
  mts:{title:'Mobility Transportation Services: patient FAQs',url:'https://mobilitydispatch.com/faqs.php'},
  dream:{title:'Dream Care Rides: transportation guide',url:'https://dreamcarerides.com/guides/non-emergency-medical-transportation'},
  local:{title:'Call The Care: Fort Worth transportation',url:'https://www.callthecare.com/fort-worth'},
  texas:{title:'Texas HHSC: Medical Transportation Program',url:'https://www.hhs.texas.gov/services/health/medicaid-chip/medicaid-chip-members/nonemergency-medical-transportation-program'},
  medicare:{title:'Medicare.gov: ambulance coverage',url:'https://www.medicare.gov/coverage/ambulance-services'}
 };
 const contact='Call Compassion Care Transport at 214-566-3869 or email Compassioncaretransport@yahoo.com.';
 const aliases=[['hospital',/discharg|released? from|leaving (the )?hospital|ride home from (the )?hospital/],['dialysis',/dialysis|renal|kidney/],['rehabilitation',/rehab|physical therap|occupational therap|therapy|recovery appointment/],['facility',/nursing|assisted living|care facility|facility|resident|senior living/],['wheelchair',/wheelchair|power chair|scooter|wheel chair/],['ambulatory',/ambulatory|walker|cane|crutch|walk independently/],['doctor',/doctor|clinic|check.?up|appointment|outpatient/]];
 function answer(question,context={}){
  const q=String(question||'').toLowerCase().replace(/[’]/g,"'").trim();
  const clean=q.replace(/non[ -]?emergency/g,'');
  const services=root.compassionCareServices||[];const hit=aliases.find(([,re])=>re.test(q));
  let key=hit?.[0]||context.service||null;const entry=services.find(s=>s.key===key);
  const reply=(text,ids=[],service=key)=>({text,service,sources:ids.map(id=>sources[id]).filter(Boolean)});
  if(/chest pain|can'?t breathe|cannot breathe|trouble breathing|severe bleeding|unconscious|stroke symptoms|medical emergency|emergency right now|call 911/.test(clean))return reply('If this is an emergency, call 911 now. Compassion Care provides non-emergency transportation; this website cannot dispatch emergency help or provide clinical assessment.',[],null);
  if(/social security|ssn|insurance id|medicaid id|medical records/.test(q))return reply('Please do not enter Social Security numbers, insurance IDs or medical records in this public chat. For trip planning, share only your general mobility needs and appointment logistics. Use your health plan’s official contact for benefit verification. '+contact,['texas']);
  if(/medicaid|med trip|877.?633|state program/.test(q))return reply('Texas HHSC has a Medical Transportation Program for eligible people who lack another way to reach covered care. If you have a Medicaid health plan, contact that plan’s transportation line. If you do not have a health plan, HHSC lists 877-633-8747.\n\nEligibility, authorization and approved transportation providers must be checked through the program. Compassion Care’s Medicaid enrollment or acceptance has not been confirmed. '+contact,['texas']);
  if(/medicare/.test(q))return reply('Medicare’s ambulance benefit has specific medical-necessity conditions. A routine non-emergency van ride is not automatically covered just because it is for a medical appointment. Ask your plan about the exact trip, provider eligibility and any authorization requirements. Compassion Care’s Medicare or plan-billing arrangements have not been confirmed. '+contact,['medicare']);
  if(/how much|insurance|coverage|covered|pay|payment|price|pricing|cost|quote|fare|rate|fee|discount/.test(q))return reply('The team needs the pickup and destination, required arrival, mobility needs and return plan to review a quote. Ask whether waiting, a companion or a second journey changes the total. Compassion Care’s rates, payment methods and insurer arrangements are not yet confirmed in this assistant. '+contact,['local']);
  if(/ambulatory/.test(q)&&/wheelchair/.test(q)&&/difference|versus| vs |compare/.test(q))return reply('Ambulatory transportation is planned for someone who can walk and board with the agreed assistance, possibly using a cane or walker. Wheelchair transportation requires a suitable accessible vehicle and chair/passenger securement arrangements. The trip reason—such as dialysis or a doctor visit—is separate from the mobility type. Tell the team how the passenger travels so they can check suitability.',['dream','local']);
  if(/oxygen|monitor|nurse|paramedic|medical treatment|stretcher|gurney|bed.?to.?bed|cannot sit|can'?t sit|lay flat|lie flat|lifting|lift me|carry me/.test(q))return reply('The seven confirmed services cover ambulatory and wheelchair journeys plus appointment, discharge and facility transportation. Stretcher vehicles, oxygen provision, lifting and clinical staff are not confirmed capabilities. Describe the need before requesting a trip; your healthcare team should advise which transport type is appropriate. Do not assume a regular van ride includes medical care. '+contact,['dream','local']);
  if(/stair|steps|ramp|elevator|door.?to.?door|door.?through|curb|entrance|inside (the )?building/.test(q))return reply('Describe the route from the passenger’s doorway to the vehicle and from the vehicle to the destination: steps, ramps, elevators, narrow doors and uneven paths all matter. Curbside, doorway and inside-building assistance are different service levels. Compassion Care must confirm the help available for your trip; stair carrying or lifting is not assumed. '+contact,['dream','local']);
  if(/family|companion|caregiver|ride along|accompany|escort|bring someone/.test(q))return reply('Ask for companion or caregiver space when requesting the ride. Tell the team who is accompanying the passenger and what help they will provide. Vehicle seating, assistance responsibilities and any charges need confirmation. For a procedure with sedation, also check the clinic’s responsible-adult and discharge requirements.',['mts','local']);
  if(/sedat|anesthe|anaesthe|surgery|procedure/.test(q)&&/escort|alone|ride|home|adult/.test(q))return reply('Ask the clinic which escort and discharge arrangements it requires after the procedure. A transport ride alone may not meet its responsible-adult requirement. Coordinate the clinic’s instructions with the transportation team before accepting a pickup time.',['dream']);
  if(/cancel|reschedul|late|delay|running behind|missed|no.?show|wait|return|round.?trip|one.?way|will.?call/.test(q))return reply('Plan the outward and return journeys separately. A fixed return pickup, a call-when-ready request and a driver waiting on site are different arrangements. Tell the team promptly if your appointment or discharge timing changes. Waiting availability, cancellation terms, fees and return pickup timing must be confirmed directly. '+contact,['dream','mts']);
  if(/hour|weekend|holiday|same.?day|today|tonight|24.?7|advance|notice|how soon/.test(q))return reply('Request transportation as early as you can, especially for a repeated schedule or specialized access needs. Compassion Care’s hours, minimum notice, same-day availability and weekend arrangements have not been confirmed here. '+contact,['mts','local']);
  if(/child|minor|pediatric|car seat|booster|pet|service animal/.test(q))return reply('Tell the team in advance about a child passenger, required seating, an accompanying adult or an animal. Compassion Care’s age, seating and animal arrangements must be confirmed for the trip. Texas program rules and any health-plan requirements are separate from the company’s own booking policies. '+contact,['texas']);
  if(/dallas|fort worth|dfw|service area|which cit|where do you|long.?distance|out.of.state/.test(q))return reply('Compassion Care Transport’s confirmed service area is Dallas–Fort Worth. Provide the actual pickup and destination so the team can review the route. Specific city limits, trip-distance limits and out-of-area journeys require confirmation. '+contact);
  if(/phone|telephone|number|email|contact|human|manager/.test(q))return reply(contact);
  if(/book|reserv|schedule|confirm|availability/.test(q)&&!entry)return reply('Use Plan a ride request to review your details and prepare an email, or call 214-566-3869. The team must confirm the vehicle, assistance, availability and pickup arrangements. This assistant does not reserve a vehicle or book a calendar appointment.');
  if(/what is nemt|what does nemt|non[ -]?emergency|ambulance|emergency/.test(q))return reply('Non-emergency medical transportation helps people reach planned healthcare when they need transportation assistance. Mobility and access needs determine the suitable vehicle and support. It is different from emergency ambulance response or clinical care during a journey. For an immediate emergency, call 911.',['dream']);
  if(entry){
   if(/bring|prepare|information|details|need to tell|what do you need/.test(q))return {text:'For '+entry.title.toLowerCase()+', have these details ready:\n• '+entry.prepare.join('\n• ')+'\n\nAlso provide both addresses and the time you must arrive. The team confirms the plan before a ride is accepted.',service:key,sources:entry.sources};
   if(/include|comprise|cover|involve|expect/.test(q))return {text:entry.overview+'\n\nWe plan with you:\n• '+entry.includes.join('\n• '),service:key,sources:entry.sources};
   if(/stay|remain/.test(q)&&key==='wheelchair')return {text:entry.faqs[0].a+' '+contact,service:key,sources:entry.sources};
   return {text:entry.who+'\n\n'+entry.overview+'\n\nYou can ask what to prepare, how the return works, or how to request this service.',service:key,sources:entry.sources};
  }
  return reply('I can explain our seven transportation services, wheelchair and walking-aid planning, discharge coordination, repeated appointments, companions, access needs and how to request a ride. What kind of journey are you planning? For an individual quote or a policy decision, call 214-566-3869.',[],null);
 }
 root.CareKnowledge={answer,sources,reviewed:'2026-11-07'};
})(typeof window!=='undefined'?window:globalThis);
